      const timingRows = [...timingText.matchAll(/\[frade:p02:(main|relay)\] (?:([a-z.]+) )?([0-9]+(?:\.[0-9]+)?)(?: \[frade:p02:renderer\] ([a-z.]+) ([0-9]+(?:\.[0-9]+)?))?/g)].map(row => ({ source: row[1], phase: row[4] ?? row[2], mainClock: Number(row[3]), ...(row[5] ? { rendererClock: Number(row[5]) } : {}) }))
