        spawnSync(join(process.env.WINDIR!, 'System32/taskkill.exe'), ['/PID', String(child.pid), '/T', '/F'], { windowsHide: true, timeout: 10000 })
        await expect.poll(() => ownedTree.filter(alive)).toEqual([])
      }
      await fs.utimes(source, stat.atime, stat.mtime)
      expect(await fs.readFile(source)).toEqual(original)
      await cleanupProfile(profile, parent)
    }
  })
